const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE CONFIGURATION
// ============================================

// Security headers for common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Configure CORS (restrict to specific origins in production)
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Body size limits to prevent DoS attacks
app.use(express.json({ 
  limit: '10kb',
  strict: true 
}));

// Rate limiting to prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
    });
  },
});

app.use('/api', limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// Request logging for security auditing
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logData = {
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      ip: req.ip || req.connection.remoteAddress,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      userAgent: req.get('user-agent'),
    };

    // In production, send to a secure logging service
    if (res.statusCode >= 400) {
      console.error('[SECURITY]', JSON.stringify(logData));
    }
  });

  next();
});

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

/**
 * Sanitize and validate input parameters
 */
function validateParams(params, schema) {
  const errors = [];

  for (const [key, rules] of Object.entries(schema)) {
    const value = params[key];

    // Required field check
    if (rules.required && (value === undefined || value === null || value === '')) {
      errors.push(`${key} is required`);
      continue;
    }

    // Skip validation if field is optional and not provided
    if (!rules.required && (value === undefined || value === null)) {
      continue;
    }

    // Type validation
    if (rules.type && typeof value !== rules.type) {
      errors.push(`${key} must be of type ${rules.type}`);
      continue;
    }

    // String validations
    if (typeof value === 'string') {
      // Length validation
      if (rules.minLength && value.length < rules.minLength) {
        errors.push(`${key} must be at least ${rules.minLength} characters`);
      }
      if (rules.maxLength && value.length > rules.maxLength) {
        errors.push(`${key} must not exceed ${rules.maxLength} characters`);
      }

      // Pattern validation (regex)
      if (rules.pattern && !rules.pattern.test(value)) {
        errors.push(`${key} contains invalid characters`);
      }

      // SQL injection / XSS prevention - basic sanitization
      if (rules.noSpecialChars && /[^a-zA-Z0-9\s\-_]/.test(value)) {
        errors.push(`${key} contains special characters that are not allowed`);
      }
    }

    // Number validations
    if (typeof value === 'number') {
      if (rules.min !== undefined && value < rules.min) {
        errors.push(`${key} must be at least ${rules.min}`);
      }
      if (rules.max !== undefined && value > rules.max) {
        errors.push(`${key} must not exceed ${rules.max}`);
      }
    }

    // Array validations
    if (rules.isArray && !Array.isArray(value)) {
      errors.push(`${key} must be an array`);
    }
    if (rules.isArray && Array.isArray(value)) {
      if (rules.maxItems && value.length > rules.maxItems) {
        errors.push(`${key} must not contain more than ${rules.maxItems} items`);
      }
    }
  }

  return errors;
}

/**
 * Sanitize output data to remove sensitive fields
 */
function sanitizeOutput(data, allowedFields = []) {
  if (Array.isArray(data)) {
    return data.map(item => sanitizeObject(item, allowedFields));
  }
  return sanitizeObject(data, allowedFields);
}

function sanitizeObject(obj, allowedFields) {
  const sanitized = {};
  for (const key of allowedFields) {
    if (obj.hasOwnProperty(key)) {
      sanitized[key] = obj[key];
    }
  }
  return sanitized;
}

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * Centralized error handler
 */
app.use((err, req, res, next) => {
  // Log error details
  console.error('[ERROR]', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      code: err.code || 'INTERNAL_ERROR',
      ...(isDevelopment && { stack: err.stack }),
    },
  });
});

/**
 * 404 handler - must be after all routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      code: 'NOT_FOUND',
      path: req.path,
    },
  });
});

/**
 * Async handler wrapper to catch errors in async route handlers
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// ============================================
// ROUTES WITH SECURITY MEASURES
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  // Only return minimal information
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/**
 * Get users with pagination and filtering
 */
app.get('/users', asyncHandler(async (req, res) => {
  // Validate query parameters
  const querySchema = {
    page: { type: 'number', min: 1, max: 1000 },
    limit: { type: 'number', min: 1, max: 100 },
    sortBy: { type: 'string', noSpecialChars: true, maxLength: 50 },
    sortOrder: { type: 'string', pattern: /^(asc|desc)$/i },
    search: { type: 'string', maxLength: 100, noSpecialChars: false },
  };

  const validationErrors = validateParams(req.query, querySchema);
  if (validationErrors.length > 0) {
    const error = new Error('Validation failed');
    error.status = 400;
    error.code = 'VALIDATION_ERROR';
    error.details = validationErrors;
    throw error;
  }

  // Set defaults with validated values
  const page = parseInt(req.query.page) || 1;
  const limit = Math.min(parseInt(req.query.limit) || 10, 100);

  // Mock data (replace with actual database query)
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filtering if search parameter provided
  let filteredUsers = allUsers;
  if (req.query.search) {
    const searchTerm = req.query.search.toLowerCase();
    filteredUsers = allUsers.filter(user => 
      user.name.toLowerCase().includes(searchTerm) ||
      user.email.toLowerCase().includes(searchTerm)
    );
  }

  // Pagination
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

  // Sanitize output - only expose necessary fields
  const sanitizedUsers = sanitizeOutput(paginatedUsers, ['id', 'name', 'email']);

  res.json({
    data: sanitizedUsers,
    pagination: {
      page,
      limit,
      total: filteredUsers.length,
      totalPages: Math.ceil(filteredUsers.length / limit),
    },
  });
}));

/**
 * Get user by ID
 */
app.get('/users/:id', strictLimiter, asyncHandler(async (req, res) => {
  // Validate path parameter
  const paramSchema = {
    id: { 
      type: 'string', 
      pattern: /^\d+$/,
      required: true,
    },
  };

  const validationErrors = validateParams(req.params, paramSchema);
  if (validationErrors.length > 0) {
    const error = new Error('Invalid user ID');
    error.status = 400;
    error.code = 'VALIDATION_ERROR';
    error.details = validationErrors;
    throw error;
  }

  const userId = parseInt(req.params.id);

  // Validate ID range
  if (userId < 1 || userId > 1000000) {
    const error = new Error('User ID out of valid range');
    error.status = 400;
    error.code = 'INVALID_ID_RANGE';
    throw error;
  }

  // Mock data lookup (replace with actual database query)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', internalId: 'SYS-001' },
    { id: 2, name: 'Bob', email: 'bob@example.com', internalId: 'SYS-002' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    const error = new Error('User not found');
    error.status = 404;
    error.code = 'USER_NOT_FOUND';
    throw error;
  }

  // Sanitize output - exclude internal fields
  const sanitizedUser = sanitizeOutput(user, ['id', 'name', 'email']);

  res.json({ data: sanitizedUser });
}));

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('[UNCAUGHT EXCEPTION]', err);
  shutdown('UNCAUGHT_EXCEPTION');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED REJECTION]', reason);
  shutdown('UNHANDLED_REJECTION');
});

module.exports = app;

# Security Review & Recommendations for app.js

## Executive Summary

The original `app.js` file has several critical security vulnerabilities and lacks essential security controls. This document outlines the identified issues and provides concrete recommendations to improve error handling, input validation, and overall security posture.

---

## Vulnerabilities Identified

### 🔴 Critical Issues

| # | Issue | Impact | Likelihood |
|---|-------|--------|------------|
| 1 | No input validation on any endpoint | Injection attacks, data corruption | High |
| 2 | No rate limiting | DoS attacks, brute force | High |
| 3 | No security headers | XSS, clickjacking, MITM | Medium |
| 4 | No error handling | Information disclosure (stack traces) | Medium |
| 5 | Unrestricted data exposure | Sensitive data leakage | Medium |

### 🟡 Medium Issues

| # | Issue | Impact |
|---|-------|--------|
| 6 | No request size limits | Memory exhaustion attacks |
| 7 | No CORS configuration | Unauthorized cross-origin access |
| 8 | No logging/auditing | No incident forensics capability |
| 9 | No graceful shutdown | Data corruption on restart |
| 10 | Hardcoded values in responses | Information disclosure |

---

## Detailed Recommendations

### 1. Input Validation

**Problem:** The current code accepts any input without validation, making it vulnerable to:
- SQL injection (when connected to a database)
- NoSQL injection
- XSS attacks
- Parameter pollution attacks

**Solution:**
```javascript
// Add validation middleware and schema validation
function validateParams(params, schema) {
  // Validate required fields, types, patterns, lengths
  // See full implementation in app.improved.js
}

// Use it in routes
const querySchema = {
  page: { type: 'number', min: 1, max: 1000 },
  limit: { type: 'number', min: 1, max: 100 },
  email: { type: 'string', pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/ }
};
```

**Best Practices:**
- ✅ Validate all input parameters (query, path, body, headers)
- ✅ Use allow-listing approach (whitelist valid values)
- ✅ Implement server-side validation (never trust client-side)
- ✅ Sanitize output to remove internal fields
- ✅ Validate types, ranges, patterns, and lengths

---

### 2. Rate Limiting

**Problem:** Without rate limiting, attackers can:
- Launch DoS attacks by overwhelming the server
- Perform brute force attacks on authentication
- Scrape/exfiltrate data unrestricted

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: { error: 'Too many requests' }
});

// Stricter limits for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 requests per 15 minutes
});
```

**Recommended Limits:**
- General API: 100 requests/15 minutes
- Authentication endpoints: 5 requests/15 minutes
- Admin endpoints: 10 requests/hour

---

### 3. Security Headers

**Problem:** Missing security headers expose the application to:
- Clickjacking attacks
- XSS attacks
- MIME-sniffing attacks
- Information disclosure

**Solution:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));
```

**Headers Added:**
- `Content-Security-Policy` - Prevents XSS
- `X-Content-Type-Options: nosniff` - Prevents MIME-sniffing
- `X-Frame-Options: DENY` - Prevents clickjacking
- `Strict-Transport-Security` - Enforces HTTPS
- `X-XSS-Protection` - XSS filtering

---

### 4. Error Handling

**Problem:** Unhandled errors can:
- Expose stack traces and sensitive information
- Crash the application
- Leave connections hanging

**Solution:**
```javascript
// Centralized error handler
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log full error details securely
  console.error('[ERROR]', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: isDevelopment ? err.stack : undefined,
    path: req.path,
    ip: req.ip
  });

  // Send sanitized response to client
  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      code: err.code || 'INTERNAL_ERROR',
      // Only include stack in development
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// Async handler wrapper
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}
```

**Best Practices:**
- ✅ Never expose stack traces in production
- ✅ Use generic error messages for clients
- ✅ Log full error details server-side
- ✅ Handle promise rejections properly
- ✅ Use error codes for client handling

---

### 5. Request Size Limits

**Problem:** Unlimited request sizes can lead to:
- Memory exhaustion (DoS)
- Slow request attacks
- Server resource depletion

**Solution:**
```javascript
app.use(express.json({ 
  limit: '10kb',  // Restrict JSON body size
  strict: true    // Only accept objects/arrays
}));
```

**Recommended Limits:**
- JSON body: 10kb (standard API requests)
- File uploads: Use separate limits per endpoint type
- URL parameters: 2kb maximum

---

### 6. CORS Configuration

**Problem:** Without CORS controls:
- Any website can make requests to your API
- Potential for CSRF attacks
- Data can be accessed by unauthorized origins

**Solution:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

---

### 7. Logging & Auditing

**Problem:** No logging means:
- Cannot detect attacks in progress
- No forensic evidence after incidents
- Difficult to debug issues

**Solution:**
```javascript
// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const logData = {
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      ip: req.ip,
      statusCode: res.statusCode,
      duration: `${Date.now() - startTime}ms`,
      userAgent: req.get('user-agent')
    };

    // Log errors separately
    if (res.statusCode >= 400) {
      console.error('[SECURITY]', JSON.stringify(logData));
    }
  });

  next();
});
```

**Recommended Events to Log:**
- All failed authentication attempts
- Authorization failures
- Rate limit violations
- Input validation failures
- Errors (with safe details)
- High-value resource access

---

### 8. Output Sanitization

**Problem:** Returning all object fields can expose:
- Internal IDs and system fields
- Password hashes or tokens
- Configuration data

**Solution:**
```javascript
function sanitizeOutput(data, allowedFields) {
  if (Array.isArray(data)) {
    return data.map(item => sanitizeObject(item, allowedFields));
  }
  return sanitizeObject(data, allowedFields);
}

function sanitizeObject(obj, allowedFields) {
  const sanitized = {};
  for (const key of allowedFields) {
    if (obj.hasOwnProperty(key)) {
      sanitized[key] = obj[key];
    }
  }
  return sanitized;
}

// Usage
const sanitizedUsers = sanitizeOutput(users, ['id', 'name', 'email']);
```

---

### 9. Graceful Shutdown

**Problem:** Abrupt shutdowns can:
- Drop in-flight requests
- Corrupt data
- Leave connections open

**Solution:**
```javascript
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

---

## Additional Security Recommendations

### Environment Variables
```bash
# Never hardcode sensitive values
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=https://trustedsite1.com,https://trustedsite2.com
DATABASE_URL=...
API_SECRET_KEY=...
```

### Dependencies Management
```bash
# Regularly audit dependencies
npm audit
npm audit fix

# Use npm ci for clean installs in production
npm ci
```

### Additional Middleware to Consider
- `compression` - Enable gzip compression
- `express-slow-down` - Gradual slowdown for rate limit violations
- `express-mongo-sanitize` - NoSQL injection prevention
- `hpp` - HTTP Parameter Pollution protection

---

## Security Checklist

Before deploying to production:

- [ ] All inputs are validated (type, length, pattern, range)
- [ ] Rate limiting is configured for all endpoints
- [ ] Security headers are properly configured
- [ ] Error handling doesn't expose sensitive information
- [ ] Request size limits are in place
- [ ] CORS is properly restricted
- [ ] Logging captures security events
- [ ] Output is sanitized to remove internal fields
- [ ] Graceful shutdown is implemented
- [ ] HTTPS is enforced (behind reverse proxy)
- [ ] Dependencies are up-to-date and audited
- [ ] Environment variables are used for configuration
- [ ] API endpoints implement proper authentication/authorization
- [ ] Database queries use parameterized statements
- [ ] File uploads are validated and restricted
- [ ] Session management is secure (httpOnly, secure cookies)

---

## Required Dependencies

Add to `package.json`:

```json
{
  "dependencies": {
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "cors": "^2.8.5",
    "express-validator": "^7.0.1"
  }
}
```

---

## Testing Your Security Measures

1. **Test Rate Limiting:**
```bash
for i in {1..150}; do curl http://localhost:3000/api/health; done
```

2. **Test Input Validation:**
```bash
# Test SQL injection attempt
curl "http://localhost:3000/users?search=' OR '1'='1"

# Test XSS attempt
curl "http://localhost:3000/users?search=<script>alert('xss')</script>"
```

3. **Test Error Handling:**
```bash
curl "http://localhost:3000/users/invalid"
curl "http://localhost:3000/users/999999999"
```

---

## Conclusion

The improved version (`app.improved.js`) implements all the security recommendations above. Review and adapt it to your specific requirements, ensuring to:

1. Update validation schemas based on your data models
2. Adjust rate limits based on your traffic patterns
3. Configure allowed origins for your specific use case
4. Set up proper logging infrastructure
5. Implement authentication/authorization where needed

Remember: Security is an ongoing process, not a one-time setup. Regular audits, dependency updates, and monitoring are essential for maintaining a secure application.

