const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many authentication attempts, please try again later.',
});

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn(`Validation failed: ${JSON.stringify(errors.array())}`, {
      ip: req.ip,
      path: req.path,
      timestamp: new Date().toISOString()
    });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Global error handling middleware
const errorHandler = (err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error occurred:', {
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't leak sensitive error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { details: err.message, stack: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path
  });
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', 
  [
    // Validate query parameters with sanitization
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape() // Prevent XSS
      .isLength({ max: 100 })
      .withMessage('Search term too long')
      .matches(/^[a-zA-Z0-9\s\-@.]+$/)
      .withMessage('Search term contains invalid characters')
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filtering based on validated query params
      let filteredUsers = users;

      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchTerm) ||
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Apply pagination
      const offset = req.query.offset || 0;
      const limit = req.query.limit || 10;
      const paginationStart = offset;
      const paginationEnd = offset + limit;

      const paginatedUsers = filteredUsers.slice(paginationStart, paginationEnd);

      // Safe JSON response
      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          offset,
          limit,
          hasMore: paginationEnd < filteredUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// User by ID endpoint with parameter validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt()
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === req.params.id);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          id: req.params.id
        });
      }

      res.json({ data: user });
    } catch (error) {
      next(error);
    }
  }
);

// Example authenticated endpoint (requires JWT)
// app.post('/login', authLimiter, [
//   body('email').isEmail().normalizeEmail().trim(),
//   body('password').isLength({ min: 8, max: 128 })
// ], handleValidationErrors, async (req, res, next) => {
//   try {
//     // Authentication logic here
//   } catch (error) {
//     next(error);
//   }
// });

// Apply error handlers after all routes
app.use(notFoundHandler);
app.use(errorHandler);

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

