// Improved application with security best practices
// Environment-based configuration
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ==========================================
// SECURITY MIDDLEWARE
// ==========================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600 // Preflight cache duration in seconds
}));

// Body parsing with size limits (prevent DoS)
app.use(express.json({ 
  limit: '1mb',
  strict: true
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '1mb' 
}));

// Request logging
app.use(morgan(
  NODE_ENV === 'production' ? 'combined' : 'dev',
  {
    skip: (req) => req.path === '/health' // Skip logging health checks
  }
));

// Rate limiting (prevent DoS/brute force)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  // Skip rate limiting for trusted IPs
  skip: (req) => {
    const trustedIPs = process.env.TRUSTED_IPS?.split(',') || [];
    return trustedIPs.includes(req.ip);
  }
});

// Stricter rate limiting for sensitive operations
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: {
    error: 'Too many authentication attempts, please try again later.'
  }
});

app.use('/api/', apiLimiter);

// ==========================================
// VALIDATION HELPERS
// ==========================================

/**
 * Validates request query parameters against a Joi schema
 * @param {Joi.Schema} schema - Joi validation schema
 */
const validateQuery = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query, {
      abortEarly: false,
      stripUnknown: true // Remove unknown properties
    });

    if (error) {
      return res.status(400).json({
        error: 'Query validation failed',
        details: error.details.map(d => ({
          field: d.path.join('.'),
          message: d.message
        }))
      });
    }

    req.query = value;
    next();
  };
};

/**
 * Validates request body against a Joi schema
 * @param {Joi.Schema} schema - Joi validation schema
 */
const validateBody = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      return res.status(400).json({
        error: 'Request body validation failed',
        details: error.details.map(d => ({
          field: d.path.join('.'),
          message: d.message
        }))
      });
    }

    req.body = value;
    next();
  };
};

/**
 * Sanitizes string input to prevent XSS
 * @param {string} str - String to sanitize
 */
const sanitizeString = (str) => {
  if (typeof str !== 'string') return str;
  return str
    .replace(/[<>]/g, '') // Remove potential HTML tags
    .trim();
};

// ==========================================
// ROUTES
// ==========================================

// Health check endpoint (no rate limiting needed)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: NODE_ENV
  });
});

// Query parameter validation schema for /users
const usersQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sort: Joi.string().valid('id', 'name', 'email').default('id'),
  order: Joi.string().valid('asc', 'desc').default('asc')
});

// Users endpoint with input validation
app.get('/users', validateQuery(usersQuerySchema), (req, res) => {
  try {
    const { limit, offset, sort, order } = req.query;

    // Mock data - in production, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (order === 'asc') {
        return a[sort] > b[sort] ? 1 : -1;
      } else {
        return a[sort] < b[sort] ? 1 : -1;
      }
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit,
        offset,
        page: Math.floor(offset / limit) + 1
      }
    });
  } catch (error) {
    // Log error for debugging (but don't expose details to client)
    console.error('Error in /users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// User creation with body validation
const createUserSchema = Joi.object({
  name: Joi.string()
    .min(2)
    .max(100)
    .pattern(/^[a-zA-Z\s'-]+$/) // Only allow letters, spaces, hyphens, apostrophes
    .required()
    .messages({
      'string.pattern.base': 'Name can only contain letters, spaces, hyphens, and apostrophes'
    }),
  email: Joi.string()
    .email()
    .max(255)
    .required()
    .lowercase(), // Normalize to lowercase
  age: Joi.number()
    .integer()
    .min(13)
    .max(120)
    .optional()
});

app.post('/users', validateBody(createUserSchema), (req, res) => {
  try {
    const { name, email, age } = req.body;

    // Additional sanitization
    const sanitizedName = sanitizeString(name);

    // In production, save to database
    const newUser = {
      id: Date.now(), // Use proper ID generation in production
      name: sanitizedName,
      email,
      age: age || null,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ error: 'Failed to create user' });
  }
});

// Example of parameter validation
app.get('/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Validate that id is a positive integer
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId <= 0 || userId !== parseFloat(id)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'ID must be a positive integer'
      });
    }

    // Mock lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'Not found',
        message: `User with ID ${userId} not found`
      });
    }

    res.json({ data: user });
  } catch (error) {
    next(error);
  }
});

// ==========================================
// ERROR HANDLING
// ==========================================

// 404 handler - must be after all other routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Method not allowed handler
app.use((req, res) => {
  res.status(405).json({
    error: 'Method Not Allowed',
    method: req.method,
    path: req.path,
    message: `Method ${req.method} not allowed for ${req.path}`
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log the error with context
  console.error('Error occurred:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.status || err.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: err.name || 'Error',
    message: err.message || 'An unexpected error occurred',
    timestamp: new Date().toISOString(),
    path: req.path
  };

  // Include stack trace only in development
  if (NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
  }

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json(errorResponse);
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Invalid JSON',
      message: 'Request body contains invalid JSON'
    });
  }

  res.status(statusCode).json(errorResponse);
});

// ==========================================
// SERVER STARTUP
// ==========================================

// Graceful shutdown handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${NODE_ENV}`);
  console.log(`Health check available at http://localhost:${PORT}/health`);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Close server gracefully
  server.close(() => {
    process.exit(1);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Close server gracefully
  server.close(() => {
    process.exit(1);
  });
});

// Handle graceful shutdown on SIGTERM
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle graceful shutdown on SIGINT
process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = { app, server };

