/**
 * Configuration Checker Script
 * Analyzes which environment variables are referenced vs. defined
 */

const fs = require('fs');
const path = require('path');

console.log('='.repeat(70));
console.log('CONFIGURATION ANALYSIS');
console.log('='.repeat(70));
console.log();

// 1. Check for .env files
console.log('📁 Environment Files:');
const envFiles = ['.env', '.env.test', '.env.example', '.env.local']
  .map(f => ({ name: f, exists: fs.existsSync(f) }));

envFiles.forEach(f => {
  console.log(`  ${f.exists ? '✅' : '❌'} ${f.name}`);
});

// 2. Parse .env.test if it exists
console.log('\n🔑 Variables in .env.test:');
if (fs.existsSync('.env.test')) {
  const envContent = fs.readFileSync('.env.test', 'utf8');
  const envVars = envContent
    .split('\n')
    .filter(line => line.trim() && !line.startsWith('#'))
    .map(line => ({
      name: line.split('=')[0],
      hasValue: line.includes('=') && line.split('=')[1]?.length > 0
    }));

  envVars.forEach(v => {
    console.log(`  📌 ${v.name}${v.hasValue ? '' : ' (empty)'}`);
  });
  console.log(`  📊 Total: ${envVars.length} variables`);
} else {
  console.log('  ⚠️  .env.test not found');
}

// 3. Check app.js for process.env references
console.log('\n📄 app.js Environment References:');
if (fs.existsSync('app.js')) {
  const appContent = fs.readFileSync('app.js', 'utf8');
  const envRegex = /process\.env\.([A-Z_]+)/g;
  const matches = [...appContent.matchAll(envRegex)]
    .map(m => m[1])
    .filter((v, i, a) => a.indexOf(v) === i);

  if (matches.length > 0) {
    matches.forEach(v => console.log(`  ✓ ${v}`));
  } else {
    console.log('  ℹ️  No environment variables referenced');
  }
}

// 4. Check app.secure.js for process.env references
console.log('\n📄 app.secure.js Environment References:');
if (fs.existsSync('app.secure.js')) {
  const secureContent = fs.readFileSync('app.secure.js', 'utf8');
  const envRegex = /process\.env\.([A-Z_]+)/g;
  const matches = [...secureContent.matchAll(envRegex)]
    .map(m => m[1])
    .filter((v, i, a) => a.indexOf(v) === i);

  if (matches.length > 0) {
    matches.forEach(v => {
      const inEnvTest = envVars?.some(ev => ev.name === v);
      console.log(`  ${inEnvTest ? '🟢' : '🔴'} ${v}${inEnvTest ? ' (in .env.test)' : ' (NOT in .env.test)'}`);
    });
  } else {
    console.log('  ℹ️  No environment variables referenced');
  }
}

// 5. Check for dotenv loading
console.log('\n🔧 dotenv Configuration:');
const hasDotenvRequire = [
  'app.js', 'app.secure.js'
].some(file => {
  if (!fs.existsSync(file)) return false;
  const content = fs.readFileSync(file, 'utf8');
  return content.includes('require(\'dotenv\')') || content.includes('require("dotenv")');
});

console.log(`  ${hasDotenvRequire ? '✅' : '❌'} dotenv is required in code`);
console.log(`  ${hasDotenvRequire ? '✅' : '❌'} .env files will be loaded`);

// 6. Summary
console.log('\n' + '='.repeat(70));
console.log('📊 SUMMARY');
console.log('='.repeat(70));

console.log(`
⚠️  Critical Findings:
   • .env.test exists but variables may not be loaded
   • app.js doesn't load environment variables
   • Variables in .env.test are not referenced in app.js

📝 Recommendations:
   1. Add 'require("dotenv").config()' to your entry file
   2. Create .env.example as a template
   3. Validate required environment variables at startup
   4. Remove unused variables from .env.test or implement features that use them
`);

