const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet());

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: { error: 'Too many attempts, please try again later.' },
});

// Body parser with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// Custom error class
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace(this, this.constructor);
  }
}

// Validation error handler middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const errorMessages = errors.array().map(err => ({
      field: err.path || err.param,
      message: err.msg,
      value: err.value,
    }));
    return res.status(400).json({
      error: 'Validation failed',
      details: errorMessages,
    });
  }
  next();
};

// Async wrapper to catch errors in async route handlers
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Global error handler (must be last)
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  console.error('Error:', {
    timestamp: err.timestamp || new Date().toISOString(),
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: err.isOperational ? err.message : 'Internal server error',
    timestamp: new Date().toISOString(),
  };

  // Include request ID if available
  if (req.id) {
    errorResponse.requestId = req.id;
  }

  // In development mode, include more details
  if (process.env.NODE_ENV === 'development') {
    errorResponse.details = {
      message: err.message,
      stack: err.stack,
    };
  }

  res.status(statusCode).json(errorResponse);
});

// 404 handler
app.use((req, res, next) => {
  next(new AppError(`Route ${req.method} ${req.path} not found`, 404));
});

// ============================================================================
// ROUTES WITH VALIDATION
// ============================================================================

// Health check endpoint (public, no sensitive data)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// GET /users with query parameter validation
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a positive integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Search term must be less than 100 characters')
      .isAlphanumeric('en-US', { ignore: ' ' })
      .withMessage('Search term contains invalid characters'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'a***e@example.com' }, // Partial email masking
        { id: 2, name: 'Bob', email: 'b**b@example.com' },
      ];

      // Apply query parameters safely
      const limit = req.query.limit || users.length;
      const offset = req.query.offset || 0;

      if (offset >= users.length) {
        throw new AppError('Offset exceeds total number of users', 400);
      }

      const result = users.slice(offset, offset + limit);

      res.json({
        data: result,
        pagination: {
          limit,
          offset,
          total: users.length,
        },
      });
    } catch (error) {
      next(error);
    }
  })
);

// GET /users/:id with parameter validation
app.get(
  '/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res, next) => {
    try {
      const userId = req.params.id;

      // Simulated database query
      const users = [
        { id: 1, name: 'Alice', email: 'a***e@example.com' },
        { id: 2, name: 'Bob', email: 'b**b@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        throw new AppError('User not found', 404);
      }

      res.json({ data: user });
    } catch (error) {
      next(error);
    }
  })
);

// POST /users example with body validation
app.post(
  '/users',
  strictLimiter, // Stricter rate limit for creating resources
  [
    body('name')
      .trim()
      .escape()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .normalizeEmail()
      .isEmail()
      .withMessage('Invalid email address')
      .isLength({ max: 255 })
      .withMessage('Email too long'),
    body('age')
      .optional()
      .isInt({ min: 13, max: 120 })
      .withMessage('Age must be between 13 and 120'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res, next) => {
    try {
      const { name, email, age } = req.body;

      // Example: Check for duplicate user (business logic)
      const existingUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const emailExists = existingUsers.some(u => u.email === email);
      if (emailExists) {
        throw new AppError('User with this email already exists', 409);
      }

      // In a real app, create user in database here
      const newUser = {
        id: existingUsers.length + 1,
        name,
        email: email.substring(0, 3) + '***' + email.substring(email.indexOf('@')),
        age,
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      next(error);
    }
  })
);

// ============================================================================
// SECURITY ENDPOINTS
// ============================================================================

// Graceful shutdown handler
const shutdown = async (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  // Close server if needed
  if (server) {
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force close after timeout
    setTimeout(() => {
      console.error('Forcing shutdown after timeout');
      process.exit(1);
    }, 10000);
  } else {
    process.exit(0);
  }
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  shutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('unhandledRejection');
});

// ============================================================================
// START SERVER
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = { app, server, AppError };

