const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for auth/sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many authentication attempts, please try again later.',
});

// Parse request bodies with size limits
app.use(express.json({ 
  limit: '10kb',
  strict: true
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to check validation results
 * If errors exist, returns 400 with error details
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for monitoring
    console.warn('Validation failed:', {
      path: req.path,
      ip: req.ip,
      errors: errors.array()
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value ? '[REDACTED]' : undefined
      }))
    });
  }
  next();
};

/**
 * Sanitize user input to prevent injection attacks
 */
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    // Remove prototype pollution attempts
    const sanitized = JSON.parse(JSON.stringify(req.body));
    req.body = sanitized;
  }
  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found on this server.',
    path: req.path
  });
});

/**
 * Global Error Handler
 * Must be defined after all routes
 */
app.use((err, req, res, next) => {
  // Log error with context
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send appropriate response
  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An unexpected error occurred. Please try again later.',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Safely serialize data to prevent prototype pollution
 */
const safeJsonSerialize = (data) => {
  try {
    return JSON.parse(JSON.stringify(data));
  } catch (error) {
    console.error('Serialization error:', error);
    return {};
  }
};

/**
 * Validate email format
 */
const isValidEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

/**
 * Validate and sanitize ID parameter
 */
const validateId = (id) => {
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId < 1 || numId > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  return numId;
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.APP_VERSION || '1.0.0'
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users with optional filtering
 * GET /users
 * Query params: limit (max 100), offset, search (alphanumeric only)
 */
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('search')
      .optional()
      .trim()
      .isLength({ max: 50 })
      .withMessage('Search term must be 50 characters or less')
      .matches(/^[a-zA-Z0-9\s\-]+$/)
      .withMessage('Search term contains invalid characters')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { limit = 10, offset = 0, search = '' } = req.query;

      // Mock user data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter users if search term provided
      let filteredUsers = allUsers;
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = allUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply pagination with validation
      const validLimit = Math.min(parseInt(limit), 100);
      const validOffset = Math.max(parseInt(offset), 0);

      const paginatedUsers = filteredUsers
        .slice(validOffset, validOffset + validLimit);

      // Safe serialization to prevent prototype pollution
      res.json({
        data: safeJsonSerialize(paginatedUsers),
        meta: {
          total: filteredUsers.length,
          limit: validLimit,
          offset: validOffset
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Create a new user
 * POST /users
 */
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s\-']+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .custom(value => {
        if (!isValidEmail(value)) {
          throw new Error('Email format is invalid');
        }
        return true;
      })
  ],
  validateRequest,
  sanitizeInput,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // Check if user already exists (mock check)
      const existingUser = users.find(u => u.email === email);
      if (existingUser) {
        const error = new Error('User with this email already exists');
        error.statusCode = 409; // Conflict
        throw error;
      }

      // Create new user (in real app, would save to database)
      const newUser = {
        id: users.length + 1,
        name: name.trim(),
        email: email.toLowerCase().trim()
      };

      users.push(newUser);

      res.status(201).json({
        message: 'User created successfully',
        data: safeJsonSerialize(newUser)
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Get a specific user by ID
 * GET /users/:id
 */
app.get('/users/:id',
  [
    // ID validation happens in route handler for path params
  ],
  (req, res, next) => {
    try {
      const userId = validateId(req.params.id);

      if (userId === null) {
        const error = new Error('Invalid user ID');
        error.statusCode = 400;
        throw error;
      }

      const user = users.find(u => u.id === userId);

      if (!user) {
        const error = new Error('User not found');
        error.statusCode = 404;
        throw error;
      }

      res.json({
        data: safeJsonSerialize(user)
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// In-memory user storage (use a proper database in production)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Only start server if this file is run directly
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

