## Common Custom Validators

### Strong Password
```javascript
const passwordValidation = (value) => {
  if (!value) return true; // Allow empty for optional fields

  const hasLower = /[a-z]/.test(value);
  const hasUpper = /[A-Z]/.test(value);
  const hasNumber = /[0-9]/.test(value);
  const hasSpecial = /[!@#$%^&*(),.?":{}|<>]/.test(value);
  const hasLength = value.length >= 12;

  if (!hasLower) throw new Error('Password must contain lowercase letter');
  if (!hasUpper) throw new Error('Password must contain uppercase letter');
  if (!hasNumber) throw new Error('Password must contain number');
  if (!hasSpecial) throw new Error('Password must contain special character');
  if (!hasLength) throw new Error('Password must be at least 12 characters');

  return true;
};

// Usage
body('password').custom(passwordValidation)
```

### Unique Email Check (with database)
```javascript
const isUniqueEmail = async (email) => {
  const user = await db.query('SELECT id FROM users WHERE email = $1', [email]);
  if (user.rows.length > 0) {
    throw new Error('Email already exists');
  }
  return true;
};

// Usage
body('email').custom(isUniqueEmail)
```

### Date Range Validation
```javascript
const isValidDateRange = (endDate, { req }) => {
  if (!req.body.start_date || !endDate) return true;

  const start = new Date(req.body.start_date);
  const end = new Date(endDate);

  if (isNaN(start.getTime()) || isNaN(end.getTime())) {
    throw new Error('Invalid dates');
  }

  if (end <= start) {
    throw new Error('End date must be after start date');
  }

  const maxRange = 365 * 24 * 60 * 60 * 1000; // 1 year
  if (end - start > maxRange) {
    throw new Error('Date range cannot exceed 1 year');
  }

  return true;
};

// Usage
body('end_date').custom(isValidDateRange)
```

### Phone Number Validation
```javascript
const isValidPhoneNumber = (phone) => {
  // Supports: +1 555-123-4567, (555) 123-4567, 555.123.4567
  const phoneRegex = /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/;
  if (!phoneRegex.test(phone)) {
    throw new Error('Invalid phone number format');
  }
  return true;
};

// Usage
body('phone').trim().custom(isValidPhoneNumber)
```

