const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security-related HTTP headers
app.use(helmet());

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many attempts, please try again later.' },
});

// Body parser with size limits to prevent payload overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// VALIDATION MIDDLEWARE
// ============================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn('Validation failed:', {
      ip: req.ip,
      path: req.path,
      errors: errors.array(),
      timestamp: new Date().toISOString()
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

/**
 * Sanitize output data to prevent information leakage
 */
const sanitizeResponse = (data) => {
  if (!data) return data;

  // Remove internal properties if any
  const sanitized = { ...data };
  delete sanitized._internal;
  delete sanitized.__v;
  delete sanitized.password;
  delete sanitized.salt;

  return sanitized;
};

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 Not Found Handler
 */
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    statusCode: 404
  });
});

/**
 * Global Error Handler
 */
app.use((err, req, res, next) => {
  // Log errors securely (avoid logging sensitive data)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.statusCode || 500;
  const response = {
    error: err.name || 'Internal Server Error',
    statusCode: statusCode,
    ...(isDevelopment && { message: err.message, stack: err.stack })
  };

  res.status(statusCode).json(response);
});

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * Validates optional query parameters
 */
app.get('/health', 
  query('format').optional().isIn(['json', 'text']).withMessage('Format must be json or text'),
  handleValidationErrors,
  (req, res) => {
    const { format } = req.query;
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    if (format === 'text') {
      res.set('Content-Type', 'text/plain');
      return res.send(`Status: ${healthData.status}\nTime: ${healthData.timestamp}`);
    }

    res.json(sanitizeResponse(healthData));
  }
);

/**
 * Users endpoint with pagination and filtering
 * Includes input validation for all parameters
 */
app.get('/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer'),
    query('sort')
      .optional()
      .matches(/^(name|email|id)(:(asc|desc))?$/)
      .withMessage('Sort must be in format: field:(asc|desc), where field is name, email, or id')
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const { limit = 10, offset = 0, id, sort } = req.query;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      let filteredUsers = users.map(sanitizeResponse);

      // Filter by ID if provided
      if (id) {
        filteredUsers = filteredUsers.filter(user => user.id === parseInt(id));
      }

      // Apply limit and offset for pagination
      const startIndex = parseInt(offset);
      const endIndex = startIndex + parseInt(limit);
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Return with metadata
      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit: parseInt(limit),
          offset: parseInt(offset),
          hasMore: endIndex < filteredUsers.length
        }
      });
    } catch (error) {
      throw new Error('Failed to fetch users');
    }
  }
);

/**
 * Create user endpoint with strict validation
 */
app.post('/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email is too long')
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // In a real app, you would save to database here
      const newUser = {
        id: Date.now(), // Simple ID generation (use proper UUID in production)
        name: sanitizeResponse({ name }).name,
        email: sanitizeResponse({ email }).email
      };

      res.status(201).json({
        message: 'User created successfully',
        data: sanitizeResponse(newUser)
      });
    } catch (error) {
      throw new Error('Failed to create user');
    }
  }
);

/**
 * Get user by ID endpoint
 */
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User Not Found',
          message: `No user found with ID: ${userId}`,
          statusCode: 404
        });
      }

      res.json({ data: sanitizeResponse(user) });
    } catch (error) {
      throw new Error('Failed to fetch user');
    }
  }
);

// ============================================
// SERVER STARTUP
// ============================================

if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  // Validate required environment variables
  const requiredEnvVars = [];
  const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

  if (missingEnvVars.length > 0) {
    console.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
    process.exit(1);
  }

  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);
    server.close(() => {
      console.log('Server closed successfully');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    process.exit(1);
  });

  process.on('unhandledRejection', (err) => {
    console.error('Unhandled Rejection:', err);
    process.exit(1);
  });
}

module.exports = app;

