const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

 ============================================================================
 SECURITY MIDDLEWARE
 ============================================================================

// HTTP security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  xframeOptions: { action: 'deny' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// Request body size limit to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.'
    });
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: {
    error: 'Too many sensitive requests from this IP'
  }
});

 ============================================================================
 LOGGING & MONITORING
 ============================================================================

// Request logger middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const clientIp = req.ip || req.connection.remoteAddress;

    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: clientIp,
      userAgent: req.get('user-agent')
    }));
  });

  next();
});

 ============================================================================
 INPUT VALIDATION HELPERS
 ============================================================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Sanitize and validate ID parameter
const validateId = [
  param('id')
    .isInt({ min: 1, max: 999999 })
    .withMessage('ID must be a positive integer')
    .toInt(),
  handleValidationErrors
];

// Validate and sanitize query parameters for user listing
const validateUserQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  query('sort')
    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Sort must be one of: name, email, id'),
  query('order')
    .optional()
    .isIn(['asc', 'desc'])
    .withMessage('Order must be either asc or desc'),
  handleValidationErrors
];

 /*!
  * Error Handler Middleware
  * Must be registered after all routes
  */
const errorHandler = (err, req, res, next) => {
  // Log the error for debugging (don't expose details in production)
  console.error(JSON.stringify({
    timestamp: new Date().toISOString(),
    error: {
      name: err.name,
      message: err.message,
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
    },
    request: {
      method: req.method,
      path: req.path,
      ip: req.ip,
      userAgent: req.get('user-agent')
    }
  }));

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.statusCode || 500;
  const response = {
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred'
  };

  // Add specific error codes for known error types
  if (err.type === 'entity.parse.failed') {
    response.error = 'Invalid JSON';
    response.message = 'Request body contains invalid JSON';
    return res.status(400).json(response);
  }

  if (err.type === 'entity.too.large') {
    response.error = 'Payload Too Large';
    response.message = 'Request body exceeds size limit';
    return res.status(413).json(response);
  }

  res.status(statusCode).json(response);
};

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
    path: req.path
  });
};

 ============================================================================
 ROUTES
 ============================================================================

/**
 * Health check endpoint
 * @route GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Handle errors gracefully
    res.status(500).json({
      error: 'Health check failed',
      message: 'Unable to retrieve server status'
    });
  }
});

/**
 * Get all users endpoint with query parameter validation
 * @route GET /users
 * @query {number} limit - Maximum number of results (1-100, default: 10)
 * @query {number} offset - Number of results to skip (default: 0)
 * @query {string} sort - Field to sort by (id, name, email)
 * @query {string} order - Sort order (asc, desc)
 */
app.get('/users', validateUserQuery, (req, res) => {
  try {
    // Apply validated query parameters with safe defaults
    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;
    const sort = req.query.sort || 'id';
    const order = req.query.order === 'desc' ? -1 : 1;

    // User data (would typically come from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Sort users by the specified field
    const sortedUsers = [...allUsers].sort((a, b) => {
      if (a[sort] < b[sort]) return -1 * order;
      if (a[sort] > b[sort]) return 1 * order;
      return 0;
    });

    // Apply pagination
    const startIndex = Math.min(offset, sortedUsers.length);
    const endIndex = Math.min(startIndex + limit, sortedUsers.length);
    const paginatedUsers = sortedUsers.slice(startIndex, endIndex);

    // Response with pagination metadata
    res.json({
      data: paginatedUsers,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
        hasMore: endIndex < sortedUsers.length
      }
    });
  } catch (error) {
    // Log internal errors without exposing stack traces
    console.error('Error fetching users:', error.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to fetch users at this time'
    });
  }
});

/**
 * Get user by ID endpoint
 * @route GET /users/:id
 * @param {number} id - User ID
 */
app.get('/users/:id', validateId, (req, res) => {
  try {
    // ID is already validated and converted to integer
    const userId = req.params.id;

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    const user = allUsers.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `User with ID ${userId} not found`
      });
    }

    res.json(user);
  } catch (error) {
    // Handle unexpected errors
    console.error('Error fetching user:', error.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to fetch user at this time'
    });
  }
});

 ============================================================================
 ERROR HANDLERS (must be last)
 ============================================================================

// Handle 404 for undefined routes
app.use(notFoundHandler);

// Global error handler
app.use(errorHandler);

 ============================================================================
 SERVER INITIALIZATION
 ============================================================================

const PORT = process.env.PORT || 3000;

if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close(() => {
      console.log('Server closed successfully');
      process.exit(0);
    });

    // Force close after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    process.exit(1);
  });

  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    process.exit(1);
  });
}

module.exports = app;

