const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// HTTP security headers
app.use(helmet());

// Body parsing with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent abuse and DoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later'
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      retryAfter: Math.round(req.rateLimit.resetTime / 1000)
    });
  }
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

// Apply rate limiter to all routes
app.use('/api/', apiLimiter);

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

/**
 * Sanitization helper to prevent NoSQL injection
 */
const sanitizeId = (value) => {
  // Only allow positive integers for IDs
  const num = parseInt(value, 10);
  if (isNaN(num) || num <= 0 || !Number.isInteger(num)) {
    throw new Error('Invalid ID format');
  }
  return num;
};

/**
 * Sanitize string inputs to prevent XSS
 */
const sanitizeString = (value, maxLength = 100) => {
  if (typeof value !== 'string') {
    throw new Error('Invalid string format');
  }
  // Remove potential XSS patterns
  const sanitized = value
    .replace(/[<>]/g, '') // Remove angle brackets
    .trim()
    .substring(0, maxLength);

  if (sanitized.length === 0) {
    throw new Error('String cannot be empty');
  }
  return sanitized;
};

/**
 * Validate email format
 */
const isValidEmail = (email) => {
  const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
  return emailRegex.test(email) && email.length <= 254;
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path,
    method: req.method
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send error response (don't expose stack in production)
  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: statusCode === 500 ? 'An unexpected error occurred' : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

/**
 * Async error wrapper to catch errors in async route handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// ROUTES WITH VALIDATION
// ============================================================================

/**
 * GET /health
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * GET /api/users
 * Get all users with optional filtering
 */
app.get('/api/users', [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email'])
    .withMessage('Sort must be one of: id, name, email')
], handleValidationErrors, asyncHandler(async (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filters
  let filteredUsers = [...users];

  if (req.query.limit) {
    const limit = parseInt(req.query.limit, 10);
    const offset = parseInt(req.query.offset || '0', 10);
    filteredUsers = filteredUsers.slice(offset, offset + limit);
  }

  if (req.query.sort) {
    filteredUsers.sort((a, b) => a[req.query.sort].localeCompare(b[req.query.sort]));
  }

  // Never expose internal IDs or sensitive data in responses
  const sanitizedUsers = filteredUsers.map(user => ({
    name: user.name,
    email: user.email
  }));

  res.json({
    data: sanitizedUsers,
    count: sanitizedUsers.length,
    total: users.length
  });
}));

/**
 * GET /api/users/:id
 * Get a specific user by ID
 */
app.get('/api/users/:id', [
  param('id')
    .custom(sanitizeId)
    .withMessage('ID must be a positive integer')
], handleValidationErrors, asyncHandler(async (req, res) => {
  const userId = parseInt(req.params.id, 10);

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({
      error: 'User Not Found',
      message: `User with ID ${userId} does not exist`
    });
  }

  // Don't expose internal ID
  res.json({
    name: user.name,
    email: user.email
  });
}));

/**
 * POST /api/users
 * Create a new user (stricter rate limit applies)
 */
app.post('/api/users', strictLimiter, [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
    .custom(isValidEmail)
], handleValidationErrors, asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  // Additional business logic validation
  if (name.toLowerCase().includes('admin')) {
    return res.status(400).json({
      error: 'Invalid Name',
      message: 'Name cannot contain reserved words'
    });
  }

  // In a real app, you would save to database here
  // Never auto-increment IDs based on user input
  const newUser = {
    id: Math.floor(Math.random() * 1000000), // In real app, use database-generated ID
    name: sanitizeString(name, 100),
    email: email.toLowerCase()
  };

  // Log user creation (audit trail)
  console.log('User created:', {
    id: newUser.id,
    timestamp: new Date().toISOString(),
    ip: req.ip
  });

  res.status(201).json({
    message: 'User created successfully',
    data: {
      name: newUser.name,
      email: newUser.email
    }
  });
}));

/**
 * PUT /api/users/:id
 * Update a user
 */
app.put('/api/users/:id', [
  param('id')
    .custom(sanitizeId)
    .withMessage('ID must be a positive integer'),
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),
  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
], handleValidationErrors, asyncHandler(async (req, res) => {
  const userId = parseInt(req.params.id, 10);
  const { name, email } = req.body;

  if (!name && !email) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'At least one field (name or email) must be provided'
    });
  }

  // Simulate user update
  const updatedUser = {
    id: userId,
    name: name ? sanitizeString(name, 100) : 'Unknown',
    email: email ? email.toLowerCase() : 'unknown@example.com'
  };

  res.json({
    message: 'User updated successfully',
    data: {
      name: updatedUser.name,
      email: updatedUser.email
    }
  });
}));

/**
 * DELETE /api/users/:id
 * Delete a user (stricter rate limit)
 */
app.delete('/api/users/:id', strictLimiter, [
  param('id')
    .custom(sanitizeId)
    .withMessage('ID must be a positive integer')
], handleValidationErrors, asyncHandler(async (req, res) => {
  const userId = parseInt(req.params.id, 10);

  // In a real app, check if user exists and has permission to delete
  // Log deletion for audit trail
  console.log('User deletion attempted:', {
    id: userId,
    timestamp: new Date().toISOString(),
    ip: req.ip
  });

  res.json({
    message: 'User deleted successfully'
  });
}));

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Validate port
if (isNaN(PORT) || PORT < 1 || PORT > 65535) {
  console.error('Invalid PORT environment variable');
  process.exit(1);
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Security Patterns Cheat Sheet

Quick reference for implementing security patterns in Express.js applications.

---

## Input Validation Patterns

### Pattern 1: Route Validation Array

```javascript
app.get('/api/resource/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be 1-100')
], handleValidationErrors, routeHandler);
```

### Pattern 2: Body Validation

```javascript
app.post('/api/users', [
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email required'),
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name: 1-100 chars')
], handleValidationErrors, routeHandler);
```

### Pattern 3: Custom Sanitizer

```javascript
const sanitizeObjectId = (value) => {
  // Prevent NoSQL injection
  if (!/^[0-9a-fA-F]{24}$/.test(value)) {
    throw new Error('Invalid ID format');
  }
  return value;
};

// Usage
param('id').custom(sanitizeObjectId)
```

---

## Error Handling Patterns

### Pattern 1: Async Handler Wrapper

```javascript
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Usage
app.get('/api/data', asyncHandler(async (req, res) => {
  const data = await db.find();
  res.json(data);
}));
```

### Pattern 2: Validation Error Handler

```javascript
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};
```

### Pattern 3: Global Error Handler

```javascript
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  const status = err.statusCode || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal error' : err.message
  });
});
```

### Pattern 4: 404 Handler

```javascript
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path
  });
});
// Important: Place after all routes
```

---

## Sanitization Patterns

### Pattern 1: XSS Prevention

```javascript
const sanitizeString = (value, maxLength = 1000) => {
  if (typeof value !== 'string') {
    throw new Error('Invalid type');
  }
  return value
    .replace(/[<>]/g, '')  // Remove < and >
    .trim()
    .substring(0, maxLength);
};
```

### Pattern 2: SQL/NoSQL Injection Prevention

```javascript
const sanitizeSortField = (value, allowedFields) => {
  if (!allowedFields.includes(value)) {
    throw new Error('Invalid sort field');
  }
  return value;
};

// Usage
const allowed = ['id', 'name', 'createdAt'];
const sort = sanitizeSortField(req.query.sort, allowed);
db.find().sort({ [sort]: 1 });
```

### Pattern 3: Numeric Validation

```javascript
const sanitizeNumber = (value, min = 0, max = Infinity) => {
  const num = Number(value);
  if (isNaN(num) || num < min || num > max) {
    throw new Error(`Must be ${min}-${max}`);
  }
  return num;
};
```

---

## Rate Limiting Patterns

### Pattern 1: General API Limiting

```javascript
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 min
  max: 100,
  standardHeaders: true,
  legacyHeaders: false
});
app.use('/api/', apiLimiter);
```

### Pattern 2: Strict Sensitive Operations

```javascript
const strictLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,  // 1 hour
  max: 5,
  skipSuccessfulRequests: true
});
app.post('/api/reset-password', strictLimiter, ...);
```

### Pattern 3: Dynamic Rate Limiting

```javascript
const createDynamicLimiter = (getMaxRequests) => rateLimit({
  windowMs: 15 * 60 * 1000,
  max: (req) => getMaxRequests(req.user?.role),
  keyGenerator: (req) => req.user?.id || req.ip
});
```

---

## Security Headers Patterns

### Pattern 1: Helmet Configuration

```javascript
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "https://trusted.cdn.com"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));
```

### Pattern 2: CORS Configuration

```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

---

## Response Patterns

### Pattern 1: Sanitized Response

```javascript
// Don't expose internal IDs, passwords, etc.
const toPublicUser = (user) => ({
  email: user.email,
  createdAt: user.createdAt
  // No: id, password, internal fields
});
res.json({ data: users.map(toPublicUser) });
```

### Pattern 2: Paginated Response

```javascript
const { page = 1, limit = 10 } = req.query;
const offset = (page - 1) * limit;

const results = await Model.find().skip(offset).limit(limit);
const total = await Model.countDocuments();

res.json({
  data: results,
  pagination: {
    page: Number(page),
    limit: Number(limit),
    total,
    pages: Math.ceil(total / limit)
  }
});
```

### Pattern 3: Standard Success Response

```javascript
res.status(201).json({
  success: true,
  message: 'Resource created',
  data: { id: result.id }
});
```

---

## Database Security Patterns

### Pattern 1: Parameterized Queries

```javascript
// ✅ GOOD - Parameterized
const result = await db.query(
  'SELECT * FROM users WHERE id = $1',
  [userId]
);

// ❌ BAD - Concatenation (SQL injection)
const result = await db.query(
  `SELECT * FROM users WHERE id = ${userId}`
);
```

### Pattern 2: Mongoose Validation

```javascript
const userSchema = new Schema({
  email: {
