# Quick Start Guide: Securing Your Express.js App

A step-by-step guide to quickly add security best practices to any Express.js application.

---

## 📦 Step 1: Install Security Dependencies

```bash
npm install helmet express-rate-limit express-validator
```

---

## 🛡️ Step 2: Add Security Middleware (Copy & Paste)

Add these lines at the top of your app, right after creating the Express app:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ✅ SECURITY MIDDLEWARE

// Security headers
app.use(helmet());

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: { error: 'Too many requests' }
});
app.use('/api/', apiLimiter);
```

---

## ⚠️ Step 3: Add Error Handling (Copy & Paste)

Add these near the end of your app, after all routes but before `app.listen()`:

```javascript
// ✅ ERROR HANDLING

// 404 handler (place AFTER all routes)
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', path: req.path });
});

// Global error handler (place LAST)
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  const status = err.statusCode || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal error' : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Async error wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};
```

---

## ✅ Step 4: Add Validation Helper (Copy & Paste)

Add this helper for handling validation errors:

```javascript
// ✅ VALIDATION HELPER

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};
```

---

## 🔄 Step 5: Update Your Routes

Convert your existing routes to include validation. Here are common patterns:

### Pattern A: Route with Parameter

```javascript
// ❌ BEFORE (No validation)
app.get('/api/users/:id', (req, res) => {
  const user = users.find(u => u.id === req.params.id);
  res.json(user);
});

// ✅ AFTER (With validation)
app.get('/api/users/:id', [
  param('id').isInt({ min: 1 }).withMessage('ID must be positive integer')
], handleValidationErrors, asyncHandler(async (req, res) => {
  const userId = parseInt(req.params.id, 10);
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: 'User Not Found' });
  }

  // Don't expose internal ID
  res.json({ name: user.name, email: user.email });
}));
```

### Pattern B: Route with Query Parameters

```javascript
// ❌ BEFORE (No validation)
app.get('/api/users', (req, res) => {
  const limit = req.query.limit || 10;
  const data = users.slice(0, limit);
  res.json(data);
});

// ✅ AFTER (With validation)
app.get('/api/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit: 1-100'),
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be >= 1')
], handleValidationErrors, asyncHandler(async (req, res) => {
  const limit = parseInt(req.query.limit || 10, 10);
  const page = parseInt(req.query.page || 1, 10);
  const offset = (page - 1) * limit;

  const data = users.slice(offset, offset + limit);
  res.json({ data, total: users.length, page });
}));
```

### Pattern C: POST Route

```javascript
// ❌ BEFORE (No validation)
app.post('/api/users', (req, res) => {
  const { name, email } = req.body;
  users.push({ name, email });
  res.status(201).json(users[users.length - 1]);
});

// ✅ AFTER (With validation)
app.post('/api/users', [
  body('name').trim().isLength({ min: 1, max: 100 }).withMessage('Name: 1-100 chars'),
  body('email').trim().isEmail().normalizeEmail().withMessage('Valid email required')
], handleValidationErrors, asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  const newUser = {
    id: users.length + 1,
    name,
    email
  };

  users.push(newUser);

  // Log for audit trail
  console.log('User created:', { id: newUser.id, timestamp: new Date().toISOString() });

  res.status(201).json({ 
    message: 'User created',
    data: { name: newUser.name, email: newUser.email }
  });
}));
```

