const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various security HTTP headers

// Rate limiting to prevent DDoS/brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ 
  limit: '10kb', // Limit payload size to prevent DoS
  strict: true // Only accept objects and arrays
}));

// Input validation middleware
app.use(expressValidator());

// Request logging middleware (security monitoring)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Global error handler - must be last
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log error for debugging
  console.error(`[ERROR] ${err.stack}`);

  // Don't leak sensitive error details to clients
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// 404 handler - must be after all routes but before error handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Wrap route handlers with error handling
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Routes with input validation
app.get('/health', asyncHandler((req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    throw error;
  }
}));

app.get('/users', asyncHandler(async (req, res) => {
  try {
    // Validate query parameters if present
    if (req.query.limit || req.query.offset) {
      req.query = await req.getValidationResult().throw();

      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;

      // Sanitize limits to prevent excessive data exposure
      const sanitizedLimit = Math.min(Math.max(limit, 1), 100);
      const sanitizedOffset = Math.max(offset, 0);

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination safely
      const paginatedUsers = users.slice(sanitizedOffset, sanitizedOffset + sanitizedLimit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: users.length,
          limit: sanitizedLimit,
          offset: sanitizedOffset
        }
      });
    } else {
      // Return limited user data by default
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Remove sensitive fields if necessary
      const safeUsers = users.map(({ email, ...user }) => user);

      res.json(safeUsers);
    }
  } catch (error) {
    console.error('Error fetching users:', error);
    throw error;
  }
}));

// Example of a POST route with comprehensive validation
app.post('/users', asyncHandler(async (req, res) => {
  try {
    // Validate request body
    await req.checkBody({
      name: {
        notEmpty: { errorMessage: 'Name is required' },
        isLength: { options: { min: 2, max: 50 }, errorMessage: 'Name must be 2-50 characters' },
        matches: { options: /^[a-zA-Z\s\-']+$/, errorMessage: 'Name contains invalid characters' }
      },
      email: {
        notEmpty: { errorMessage: 'Email is required' },
        isEmail: { errorMessage: 'Invalid email format' },
        normalizeEmail: true
      }
    });

    const validationErrors = req.validationErrors();
    if (validationErrors) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: validationErrors 
      });
    }

    // Sanitize input
    const { name, email } = matchedData(req);

    // Process user creation...
    res.status(201).json({
      message: 'User created successfully',
      user: { name, email }
    });
  } catch (error) {
    throw error;
  }
}));

const PORT = process.env.PORT || 3000;

// Secure server startup with error handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
}).on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

// Graceful shutdown
const shutdown = (signal) => {
  console.log(`\n${signal} received. Shutting down gracefully...`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

