// Secured version of app.js with error handling and input validation
// No external dependencies required beyond Express

const express = require('express');
const app = express();

// ============================================================================
// BASIC MIDDLEWARE
// ============================================================================

// Parse JSON and URL-encoded bodies
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Remove X-Powered-By header (security best practice)
app.disable('x-powered-by');

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Validates query parameters based on schema
 * @param {Object} schema - Validation rules for each field
 */
const validateQuery = (schema) => {
  return (req, res, next) => {
    const errors = [];

    for (const [field, rules] of Object.entries(schema)) {
      const value = req.query[field];

      // Required check
      if (rules.required && (value === undefined || value === '')) {
        errors.push({ field, message: `${field} is required` });
        continue;
      }

      // Skip if optional and not provided
      if (!rules.required && (value === undefined || value === '')) {
        continue;
      }

      // Type: number
      if (rules.type === 'number' && isNaN(value)) {
        errors.push({ field, message: `${field} must be a number` });
        continue;
      }

      // Type: integer
      if (rules.type === 'integer' && (!Number.isInteger(Number(value)))) {
        errors.push({ field, message: `${field} must be an integer` });
        continue;
      }

      // Minimum value
      if (rules.min !== undefined && Number(value) < rules.min) {
        errors.push({ field, message: `${field} must be at least ${rules.min}` });
      }

      // Maximum value
      if (rules.max !== undefined && Number(value) > rules.max) {
        errors.push({ field, message: `${field} must be at most ${rules.max}` });
      }

      // String minimum length
      if (rules.minLength && String(value).length < rules.minLength) {
        errors.push({ field, message: `${field} must be at least ${rules.minLength} characters` });
      }

      // String maximum length
      if (rules.maxLength && String(value).length > rules.maxLength) {
        errors.push({ field, message: `${field} must be at most ${rules.maxLength} characters` });
      }

      // Enum validation
      if (rules.enum && !rules.enum.includes(value)) {
        errors.push({ field, message: `${field} must be one of: ${rules.enum.join(', ')}` });
      }

      // Pattern/regex validation
      if (rules.pattern && !rules.pattern.test(String(value))) {
        errors.push({ field, message: `${field} format is invalid` });
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors
      });
    }
    next();
  };
};

/**
 * Validates request body based on schema
 * @param {Object} schema - Validation rules for each field
 */
const validateBody = (schema) => {
  return (req, res, next) => {
    const errors = [];

    for (const [field, rules] of Object.entries(schema)) {
      const value = req.body[field];

      // Required check
      if (rules.required && (value === undefined || value === null || value === '')) {
        errors.push({ field, message: `${field} is required` });
        continue;
      }

      // Skip if optional and not provided
      if (!rules.required && (value === undefined || value === null)) {
        continue;
      }

      // String type
      if (rules.type === 'string' && typeof value !== 'string') {
        errors.push({ field, message: `${field} must be a string` });
        continue;
      }

      // Number type
      if (rules.type === 'number' && typeof value !== 'number') {
        errors.push({ field, message: `${field} must be a number` });
        continue;
      }

      // Email validation
      if (rules.email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(String(value))) {
          errors.push({ field, message: `${field} must be a valid email address` });
        }
      }

      // Min length
      if (rules.minLength && String(value).length < rules.minLength) {
        errors.push({ field, message: `${field} must be at least ${rules.minLength} characters` });
      }

      // Max length
      if (rules.maxLength && String(value).length > rules.maxLength) {
        errors.push({ field, message: `${field} must be at most ${rules.maxLength} characters` });
      }

      // Pattern validation
      if (rules.pattern && !rules.pattern.test(String(value))) {
        errors.push({ field, message: `${field} format is invalid` });
      }

      // Name pattern (letters, spaces, hyphens, apostrophes only)
      if (rules.isName && !/^[a-zA-Z\s\-']+$/.test(String(value))) {
        errors.push({ field, message: `${field} can only contain letters, spaces, hyphens, and apostrophes` });
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors
      });
    }
    next();
  };
};

/**
 * Sanitizes input to prevent XSS and injection attacks
 */
const sanitizeInput = (req, res, next) => {
  const sanitize = (value) => {
    if (typeof value === 'string') {
      // Remove script tags and other HTML
      let sanitized = value.replace(/<script[^>]*>.*?<\/script>/gi, '');
      sanitized = sanitized.replace(/<[^>]*>/g, ''); // Remove any remaining tags
      sanitized = sanitized.trim();
      return sanitized;
    }
    if (Array.isArray(value)) {
      return value.map(sanitize);
    }
    if (typeof value === 'object' && value !== null) {
      const sanitized = {};
      for (const key in value) {
        if (value.hasOwnProperty(key)) {
          sanitized[key] = sanitize(value[key]);
        }
      }
      return sanitized;
    }
    return value;
  };

  if (req.body) req.body = sanitize(req.body);
  if (req.query) req.query = sanitize(req.query);

  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Custom Application Error class
 */
class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Async handler wrapper to catch errors in async route handlers
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

/**
 * Handle JSON parsing errors
 */
app.use((err, req, res, next) => {
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON',
      message: 'Request body contains invalid JSON'
    });
  }
  next();
});

/**
 * 404 Not Found handler
 * Must come before global error handler
 */
app.use((req, res, next) => {
  next(new AppError(`Route ${req.method} ${req.path} not found`, 404));
});

/**
 * Global error handler - must be last middleware
 */
app.use((err, req, res, next) => {
  // Log error
  console.error('Error:', {
    message: err.message,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send error response
  res.status(statusCode).json({
    error: err.message || 'Internal Server Error',
    statusCode
  });
});

// ============================================================================
// ROUTES WITH VALIDATION
// ============================================================================

/**
 * GET /health - Health check endpoint
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    next(error);
  }
});

/**
 * GET /users - Get users with filtering, sorting, and pagination
 * Query params: page, limit, sort, order, search
 */
app.get(
  '/users',
  validateQuery({
    page: { type: 'integer', min: 1, required: false },
    limit: { type: 'integer', min: 1, max: 100, required: false },
    sort: { enum: ['id', 'name', 'email'], required: false },
    order: { enum: ['asc', 'desc'], required: false },
    search: { type: 'string', minLength: 1, maxLength: 50, required: false }
  }),
  asyncHandler(async (req, res, next) => {
    const { 
      page = 1, 
      limit = 10, 
      sort = 'id', 
      order = 'asc', 
      search 
    } = req.query;

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter
    let filteredUsers = allUsers;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = allUsers.filter(user =>
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply sorting
    filteredUsers.sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      if (aVal < bVal) return order === 'asc' ? -1 : 1;
      if (aVal > bVal) return order === 'asc' ? 1 : -1;
      return 0;
    });

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + parseInt(limit);
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      }
    });
  })
);

/**
 * GET /users/:id - Get a specific user
 */
app.get(
  '/users/:id',
  (req, res, next) => {
    // Validate ID parameter
    const userId = parseInt(req.params.id);
    if (!Number.isInteger(userId) || userId < 1) {
      return next(new AppError('Invalid user ID. Must be a positive integer.', 400));
    }
    req.userId = userId;
    next();
  },
  asyncHandler(async (req, res, next) => {
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    const user = allUsers.find(u => u.id === req.userId);

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json(user);
  })
);

/**
 * POST /users - Create a new user
 */
app.post(
  '/users',
  sanitizeInput,
  validateBody({
    name: { 
      type: 'string', 
      required: true, 
      minLength: 2, 
      maxLength: 100,
      isName: true
    },
    email: { 
      type: 'string', 
      required: true, 
      email: true,
      maxLength: 255
    }
  }),
  asyncHandler(async (req, res, next) => {
    const { name, email } = req.body;

    // Check for duplicate email (mock implementation)
