/**
 * Improved Express Application with Security Best Practices
 * 
 * Security features:
 * - Input validation and sanitization
 * - Comprehensive error handling
 * - Rate limiting
 * - Security headers
 * - Request size limits
 * - Proper logging
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limiting for auth-related endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Limit each IP to 5 requests per windowMs
  message: {
    error: 'Too many authentication attempts, please try again later.',
  },
  skipSuccessfulRequests: true,
});

app.use(limiter);

// Body parsing with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent payload overflow attacks
  strict: true,  // Only accept objects and arrays
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb',
}));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to check validation results
 * Sends 400 Bad Request if validation fails
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value,
      })),
    });
  }

  next();
};

/**
 * Middleware to safely extract user IP
 */
const getClientIp = (req) => {
  return req.ip || 
         req.connection?.remoteAddress || 
         req.socket?.remoteAddress ||
         (req.connection?.socket ? req.connection.socket.remoteAddress : null);
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Global Error Handler
 */
app.use((err, req, res, next) => {
  // Log error details (use proper logging library in production)
  const errorDetails = {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: getClientIp(req),
    timestamp: new Date().toISOString(),
  };

  console.error('Error:', JSON.stringify(errorDetails, null, 2));

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send error response
  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
    timestamp: new Date().toISOString(),
    ...(process.env.NODE_ENV === 'development' && { 
      details: err.message,
      stack: err.stack 
    }),
  });
});

// ============================================================================
// CUSTOM ERROR CLASSES
// ============================================================================

class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

class NotFoundError extends AppError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized') {
    super(message, 401);
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Forbidden') {
    super(message, 403);
  }
}

// ============================================================================
// DATABASE LAYER (Example with error handling)
// ============================================================================

/**
 * Simulated database operations with error handling
 */
const db = {
  users: [
    { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date() },
    { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: new Date() },
  ],

  getAllUsers() {
    try {
      return this.users;
    } catch (error) {
      throw new AppError('Failed to retrieve users', 500);
    }
  },

  getUserById(id) {
    try {
      // Validate ID is a positive integer
      const userId = parseInt(id, 10);
      if (isNaN(userId) || userId <= 0) {
        throw new ValidationError('Invalid user ID format');
      }

      const user = this.users.find(u => u.id === userId);
      if (!user) {
        throw new NotFoundError('User');
      }

      return user;
    } catch (error) {
      if (error instanceof AppError) {
        throw error;
      }
      throw new AppError('Failed to retrieve user', 500);
    }
  },

  createUser(userData) {
    try {
      // Validate required fields
      if (!userData.name || !userData.email) {
        throw new ValidationError('Name and email are required');
      }

      // Validate email format
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(userData.email)) {
        throw new ValidationError('Invalid email format');
      }

      // Sanitize user input
      const sanitizedUser = {
        name: userData.name.trim().replace(/[<>]/g, ''),
        email: userData.email.trim().toLowerCase(),
      };

      // Check for duplicates
      const exists = this.users.some(u => u.email === sanitizedUser.email);
      if (exists) {
        throw new AppError('User with this email already exists', 409);
      }

      const newUser = {
        id: Math.max(...this.users.map(u => u.id), 0) + 1,
        ...sanitizedUser,
        createdAt: new Date(),
      };

      this.users.push(newUser);
      return newUser;
    } catch (error) {
      if (error instanceof AppError) {
        throw error;
      }
      throw new AppError('Failed to create user', 500);
    }
  },
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get all users
 * Optional query parameters: limit, offset, sort
 */
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email', 'createdAt'])
      .withMessage('Invalid sort field'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { limit, offset, sort } = req.query;

      let users = db.getAllUsers();

      // Apply sorting
      if (sort) {
        users = [...users].sort((a, b) => {
          if (a[sort] < b[sort]) return -1;
          if (a[sort] > b[sort]) return 1;
          return 0;
        });
      }

      // Apply pagination
      const startIndex = offset || 0;
      const endIndex = limit ? startIndex + limit : undefined;
      const paginatedUsers = users.slice(startIndex, endIndex);

      // Remove sensitive fields if necessary
      const safeUsers = paginatedUsers.map(({ id, name, email }) => ({
        id,
        name,
        email,
      }));

      res.json({
        data: safeUsers,
        meta: {
          total: users.length,
          limit: limit || users.length,
          offset: offset || 0,
        },
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Get user by ID
 */
app.get(
  '/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt(),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const user = db.getUserById(req.params.id);

      // Return only safe fields
      const { id, name, email, createdAt } = user;
      res.json({ id, name, email, createdAt });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Create new user
 */
app.post(
  '/users',
  authLimiter,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z0-9\s\-']+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail(),
    body('email')
      .custom((value) => {
        // Additional email validation
        const normalized = value.toLowerCase();
        if (normalized.length > 255) {
          throw new Error('Email is too long');
        }
        return true;
      }),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      // Use validated data from express-validator
      const { name, email } = req.body;

      const newUser = db.createUser({ name, email });

      // Return only safe fields
      const { id, createdAt } = newUser;
      res.status(201).json({ 
        id,
        name,
        email,
        createdAt,
        message: 'User created successfully',
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// START SERVER
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# App.js Security Improvements Review

## Executive Summary

The original `app.js` had several critical security vulnerabilities and missing best practices. This document outlines the issues found and the comprehensive improvements made in `app-improved.js`.

---

## Critical Issues Identified

### 1. **No Input Validation**

**Original Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No validation on query parameters
});
```

**Risk:** 
- SQL injection (if using a database)
- Directory traversal attacks
- XSS vulnerabilities
- No type checking or sanitization

**Improvement:**
```javascript
app.get('/users', [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
], validateRequest, (req, res) => { ... });
```

---

### 2. **No Error Handling**

**Original Code:**
```javascript
// No error handlers at all
app.listen(3000, () => console.log('Server running'));
```

**Risk:**
- Unhandled exceptions crash the server
- Stack traces expose sensitive information
- No customer-friendly error messages

**Improvement:**
```javascript
// Custom error classes
class AppError extends Error { ... }

// Global error handler
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
    timestamp: new Date().toISOString(),
  });
});
```

---

### 3. **No Security Headers**

**Original Code:**
```javascript
// No security middleware
```

**Risk:**
- Missing HTTP Strict Transport Security (HSTS)
- No Content Security Policy (CSP)
- Vulnerable to clickjacking, MIME sniffing, XSS

**Improvement:**
```javascript
app.use(helmet({
  contentSecurityPolicy: { ... },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));
```

---

### 4. **No Rate Limiting**

**Original Code:**
```javascript
// No rate limiting
```

**Risk:**
- Denial of Service (DoS) attacks
- Brute force attacks on authentication
- Resource exhaustion

**Improvement:**
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests' },
});
app.use(limiter);
```

---

### 5. **No Request Size Limits**

**Original Code:**
```javascript
// No body parsing configured
```

**Risk:**
- Memory exhaustion attacks
- Payload overflow vulnerabilities
- Server crashes from large uploads

**Improvement:**
```javascript
app.use(express.json({ 
  limit: '10kb',
  strict: true,
}));
```

---

### 6. **Information Disclosure**

**Original Code:**
```javascript
// Errors expose full details
```

**Risk:**
- Stack traces reveal file paths, library versions
- Internal implementation details leaked
- Aids attackers in reconnaissance

**Improvement:**
```javascript
// In production, show minimal information
res.status(statusCode).json({
  error: statusCode === 500 ? 'Internal Server Error' : err.message,
  // Stack trace only in development
  ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
});
```

---

## Comprehensive Improvements Made

### A. Security Middleware

| Feature | Implementation | Purpose |
|---------|---------------|---------|
| Helmet | `app.use(helmet(...))` | Sets security HTTP headers |
| Rate Limiting | `express-rate-limit` | Prevents DoS attacks |
| Body Parser Limits | `limit: '10kb'` | Prevents payload overflow |
| Strict JSON | `strict: true` | Rejects malformed JSON |

### B. Input Validation

Using `express-validator` for comprehensive validation:

```javascript
// Validate query parameters
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('sort').optional().isIn(['id', 'name', 'email']),
], validateRequest, handler);

// Validate body
app.post('/users', [
  body('name').trim().notEmpty().isLength({ min: 1, max: 100 }),
  body('email').trim().isEmail().normalizeEmail(),
], validateRequest, handler);

// Validate URL parameters
app.get('/users/:id', [
  param('id').isInt({ min: 1 }),
], validateRequest, handler);
```

### C. Error Handling Architecture

```
┌─────────────────────────────────────────┐
│         Custom Error Classes            │
│  ┌────────────┬────────────┬─────────┐  │
│  │AppError    │ValidationError│NotFoundError │  │
│  └────────────┴────────────┴─────────┘  │
└──────────────┬──────────────────────────┘
               │
               ▼
┌─────────────────────────────────────────┐
│      Global Error Handler               │
│  - Logs errors safely                   │
│  - Returns appropriate status codes     │
│  - Sanitizes error messages             │
